export default function Dashboard(){const {children,data,loading}=useParent();const {user}=useAuth();const pathname=usePathname();const root=pathname.replace(/\/$/,"");if(loading)return <p role="status" className="rounded-xl border bg-white p-6">Loading your child&apos;s records...</p>;if(!children.length)return <p className="rounded-xl border bg-white p-6">No children are linked to your account. Please contact your school administrator.</p>;if(!data)return null;const fees=data.fees.reduce((a:any,f:any)=>({paid:a.paid+Number(f.paidAmountPKR||0),due:a.due+Number(f.remainingAmountPKR||0)}),{paid:0,due:0});const attendance=data.attendanceSummary;const today=new Intl.DateTimeFormat("en-US",{weekday:"long",timeZone:"Asia/Karachi"}).format(new Date());const classes=data.timetable.filter((t:any)=>t.dayOfWeek===today);const dayFormat=new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Karachi"});const upcoming=data.examSchedules.filter((e:any)=>dayFormat.format(new Date(e.endDate))>=dayFormat.format(new Date())).sort((a:any,b:any)=>+new Date(a.startDate)-+new Date(b.startDate));const cards=[["Attendance",attendance.total?Math.round(attendance.present/attendance.total*100)+"%":"Not recorded","academics"],...(user?.features?.includes("FINANCE")?[["Fees outstanding",money(fees.due),"fees"],["Verified payments",money(fees.paid),"fees"]]:[]),...(user?.features?.includes("EXAMINATIONS")?[["Upcoming exams",String(upcoming.length),"academics"]]:[])];return <div className="space-y-6"><header><h1 className="text-2xl font-black">Family dashboard</h1><p className="mt-2 text-sm text-zinc-500">{data.student.name} · {data.student.className}{data.student.sectionName?" / "+data.student.sectionName:""} · {data.student.academicSessionName||"Academic year not assigned"}</p></header><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label,value,route])=><Link key={label} href={root+"/"+route} className="rounded-xl border bg-white p-5 hover:border-red-300"><p className="text-sm text-zinc-500">{label}</p><p className="mt-3 text-2xl font-bold">{value}</p><p className="mt-3 text-xs font-medium text-red-600">View records →</p></Link>)}</div><div className="grid gap-6 lg:grid-cols-2"><article className="rounded-xl border bg-white p-5"><h2 className="font-bold">Today&apos;s timetable <span className="font-normal text-zinc-500">· {today}</span></h2>{classes.length?classes.map((t:any)=><div key={t._id} className="mt-4 rounded-lg bg-zinc-50 p-3 text-sm"><p className="font-semibold">{t.subjectName}</p><p className="mt-1 text-zinc-500">{t.startTime} - {t.endTime} · {t.teacherName||"Teacher not assigned"}{t.roomNumber?" · Room "+t.roomNumber:""}</p></div>):<p className="mt-4 text-sm text-zinc-500">No classes scheduled for today.</p>}<Link href={root+"/academics"} className="mt-5 inline-block text-sm text-red-600">View weekly timetable</Link></article>{user?.features?.includes("EXAMINATIONS")&&<article className="rounded-xl border bg-white p-5"><h2 className="font-bold">Exams & published results</h2>{upcoming.length?upcoming.slice(0,3).map((e:any)=><p className="mt-4 text-sm" key={e._id}>{e.title} · {new Date(e.startDate).toLocaleDateString("en-GB")}</p>):<p className="mt-4 text-sm text-zinc-500">No upcoming exams have been scheduled for this class.</p>}{data.results[0]&&<p className="mt-4 rounded-lg bg-zinc-50 p-3 text-sm">Latest result: {data.results[0].examTitle} · {data.results[0].percentage}% · Grade {data.results[0].overallGrade}</p>}<Link href={root+"/academics"} className="mt-5 inline-block text-sm text-red-600">Open academic records</Link></article>}</div><ParentUpdates href={root+"/notifications"}/><div className="grid gap-4 sm:grid-cols-3">{[["School announcements","notices","Updates published for your child's class and family."],["Notifications","notifications","Fee reminders and payment review updates."],["Documents","documents","School files, published reports and receipts."]].map(([title,route,desc])=><Link key={route} href={root+"/"+rout